# Disable CPU Power Throttling Write-Host "Disabling CPU power throttling..." -ForegroundColor Cyan # Disable power throttling via registry # 0 = Power throttling disabled, 1 = Power throttling enabled Set-ItemProperty -Path "HKLM:\SYSTEM\CurrentControlSet\Control\Power\PowerThrottling" -Name "PowerThrottlingOff" -Value 1 -Type DWord -Force -ErrorAction Stop Write-Host "CPU power throttling has been disabled." -ForegroundColor Green Write-Host "Note: This may increase power consumption and heat on laptops." -ForegroundColor Yellow